CREATE OR REPLACE FUNCTION kaoid_private.can_review_r7c() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ select auth.uid() is not null and not coalesce((auth.jwt()->>'is_anonymous')::boolean,false) and exists(select 1 from public.profiles p where p.id=auth.uid() and p.account_status='active' and p.deleted_at is null and (exists(select 1 from public.company_owners o where o.profile_id=p.id) or exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id where a.profile_id=p.id and a.is_active and r.is_active and r.code='kyc_officer' and a.starts_at<=now() and (a.expires_at is null or a.expires_at>now())))); $$; REVOKE ALL ON FUNCTION kaoid_private.can_review_r7c() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION kaoid_private.can_review_r7c() TO authenticated;;
